def get_cve(cve_id: str) -> Optional[CVEDetail]: return CVE_DATABASE.get(cve_id.upper())
def list_cisa_kev_cves() -> List[CVEDetail]: return [c for c in CVE_DATABASE.values() if c.cisa_kev]
